Object.assign(window.DETAILED_OPTION_KEY_MISMATCH||{}, {'110-33':'公告答案選項1代表A–D為正確組合、E為錯誤敘述；但第D項「SSRI治療初期比其他抗憂鬱劑更容易自殺」未獲證據支持，而第E項提到高膽固醇與傳統文獻方向相反。請核對原考訊／教材是否有題幹或答案誤植。'});
Object.assign(window.DETAILED_OPTION_NOTES,{
'110-41':{A:'正確敘述：老年女性較常接觸鎮靜安眠、止痛等精神作用處方藥，且可能因多重處方或長期使用而發生不當使用；個別風險仍須看藥物、劑量及就醫情境。',B:'錯誤敘述：多重精神共病本身會增加物質使用風險，但本題引用資料並未支持「有多種精神共病時女性比男性更常不當使用處方藥」這個性別比較。',C:'錯誤敘述：男性平均飲酒量較高，但不能推成女性在所有年齡層或樣本中都有較多飲酒相關問題；女性生理脆弱性可能使相同飲量造成較高傷害，這與問題盛行率是不同概念。',D:'正確敘述：性別、共病、既往使用史及家庭／社會環境都可能影響老年物質使用障礙風險，屬多因性而非單一病因。'},
'110-42':{'1':'錯誤敘述：強迫型人格特質有時會隨年齡變得較不僵化，但不是確定會緩解的病程規則；人格疾患通常仍需看跨情境、長期功能影響。','2':'錯誤敘述：類分裂型人格的社交退縮可能表面上減少衝突，但不能據此推論核心冷漠與親密需求障礙會隨年齡緩解。','3':'正確敘述（依老年人格發展模型）：邊緣型人格進入晚年可能需要回顧與整合生命經驗（reflection）及建立可理解的生活秩序（systematization），以因應角色、健康與關係變化。','4':'錯誤敘述：迴避型人格的孤立與社交焦慮可能造成適應困難，但本項把它限定為老年躁症族群較差 outcome，欠缺可概括的臨床依據；人格疾患與躁症病程須分別評估。','5':'錯誤敘述：老年期發展任務中的互惠與親密較符合邊緣型人格的人際發展議題；本題所引模型將思覺失調型人格的焦點放在反思與系統化，非此配對。'},
'110-43':{A:'正確敘述：憂鬱、情緒壓力及精神疾患會降低生理與認知儲備，屬譫妄易感體質因素之一；患者同時發生急性變化時仍應尋找誘發病因。',B:'正確敘述：低活動、臥床或失能代表衰弱與功能儲備較差，亦增加譫妄風險；活動不足也可加重睡眠、感官與定向問題。',C:'錯誤敘述：飲水增加本身不是典型譫妄易感因子；若導致低鈉血症才可能經由電解質失衡誘發急性腦功能障礙，不能把飲水量直接視為風險。',D:'錯誤敘述：嗅覺障礙不是公認的主要譫妄體質風險項目；較穩定的危險因子包括高齡、認知障礙、衰弱、視聽障礙及多重共病。',E:'正確敘述：高齡是譫妄易感性的重要因素；男性在若干醫院樣本中風險較高，但「男性」效應會受共病與場域影響。'},
'110-44':{A:'正確敘述：晚發型思覺失調症的發病界線依分類傳統為40或45歲以後；60歲以上則另稱非常晚發型類思覺失調精神病。',B:'正確敘述：VLOSLP指60歲以後出現類思覺失調症精神病，確診前需排除失智、譫妄、感官缺損、藥物及腦部疾病。',C:'錯誤敘述：LOS不等同神經退化性疾病；晚年發病可能受感官、社會、血管或腦部變化影響，但不能把其病因定義為神經退化。',D:'正確敘述：VLOSLP相對少見突出的負性症狀，常有被害妄想與幻覺；這是群體特徵，不足以單獨診斷。',E:'正確敘述：女性較常見晚發／非常晚發精神病，特別是高齡發病樣本；此為流行病學傾向而非個人判別條件。'},
'110-45':{A:'錯誤敘述：PD精神病建議的藥物包括clozapine、pimavanserin，部分情境會審慎使用quetiapine；olanzapine常惡化動作症狀，通常不建議，因此三種都列為建議不正確。',B:'錯誤敘述：memantine沒有證據優於rivastigmine治療PD精神病；rivastigmine在PD失智及相關症狀上有較多證據，但主要適應症仍須區分。',C:'錯誤敘述：pimavanserin主要是5-HT2A反向促效／拮抗作用，不是5-HT1A阻斷劑；其作用可改善PD精神病且較少阻斷多巴胺造成運動惡化。',D:'正確敘述：apomorphine是D1-like與D2-like多巴胺受體促效劑；其治療PD精神病的證據有限且可能誘發幻覺，不能視為已證實療法。',E:'正確敘述：對藥物難治的PD精神病可由專科評估ECT；證據有限，需衡量麻醉、認知與運動症狀。'},
'110-46':{A:'正確敘述：本人可向法院聲請監護宣告；是否准許由法院依精神／心智狀況及鑑定結果裁定，診斷失智不自動等於無行為能力。',B:'正確敘述：檢察官是民法列明的聲請權人之一，可在符合要件時向法院聲請。',C:'正確敘述：社會福利機構是法律列舉的聲請權人之一；實際聲請仍須提出個案資料並由法院審理。',D:'錯誤敘述：民法列出的親屬聲請範圍為四親等內，不是五親等內；親等須依民法計算，不能把所有遠親都納入。',E:'錯誤敘述：最近一個月曾同居的其他親屬並非獨立法定聲請資格；法定權利依親屬範圍、同居關係或其他列舉身分判定，不能以此條件取代。'},
'110-47':{A:'錯誤敘述：失語、失用、失讀及失寫通常與優勢半球（多數人為左半球）皮質病灶相關，不是右半球病灶的典型組合；右半球較常見忽略或視空間缺損。',B:'正確敘述：多發性梗塞造成不同腦區散在損害，可呈現不均勻、斑駁的認知缺損（patchy deficits），其型態隨梗塞位置而變。',C:'正確敘述：小血管性皮質下病灶常累及額葉白質及額葉—皮質下迴路，導致注意力、處理速度與精神動作速度變慢。',D:'正確敘述：皮質下血管性失智相較典型AD可有較突出的執行功能與處理速度缺損；個案若合併AD病理，記憶儲存障礙也會明顯。',E:'正確敘述：Binswanger病可表現步態不穩、尿失禁、認知／執行功能下降及假性延髓性癱瘓，與廣泛白質小血管病變相關。'},
'110-48':{A:'正確敘述：AD相關精神病的盛行率常估計約35–50%，會隨病程、照護場域及妄想／幻覺定義而變。',B:'錯誤敘述：AD妄想常為被偷竊、配偶不忠、住家有陌生人或錯認等較簡單主題；複雜系統化妄想不是最典型概括。',C:'正確敘述：AD患者可出現視幻覺，尤其病程較晚或伴有其他病理時；若早期突出視幻覺，應考慮DLB、譫妄、視力問題與藥物。',D:'正確敘述：AD精神病症狀可能隨病程、環境或誘因變化而減輕甚至暫時消失，也可能復發；應先找感染、疼痛、藥物及感官因素。',E:'錯誤敘述：自殺意念不是AD精神病的常見核心表現；若出現，應評估共病憂鬱、絕望、病識感及立即安全風險。'},
'110-49':{A:'正確敘述：VLOSLP在老年發病族群女性較多，可能與壽命及感官／社會因素有關；這是盛行率趨勢。',B:'錯誤敘述：早發型思覺失調症通常有較突出的神經發展與學習／認知困難；說其學習障礙比VLOSLP少，方向顛倒。',C:'正確敘述：早發型思覺失調症的家族史及遺傳負荷通常比VLOSLP明顯；極晚發患者多數沒有明確家族史。',D:'錯誤敘述：TD風險受年齡、累積抗精神病藥暴露、性別及腦病影響，VLOSLP因高齡及藥物敏感性未必與早發型相同，不能稱兩者差不多。',E:'正確敘述：早發型患者常有較明顯負性症狀及病前功能受損；VLOSLP通常負性症狀較少，但仍有個體差異。'},
'110-50':{'1':'正確敘述：fluoxetine強力抑制CYP2D6；fluvoxamine的主要抑制靶點為CYP1A2與CYP2C19，對CYP2D6較弱，因此本項方向正確。','2':'錯誤敘述：fluvoxamine對CYP1A2有強抑制作用；paroxetine主要抑制CYP2D6，對CYP1A2不會強於fluvoxamine。', '3':'正確敘述：fluvoxamine可抑制CYP2C9，duloxetine也會抑制CYP2D6並有較弱CYP2C9作用；題目比較下fluvoxamine抑制CYP2C9較強。', '4':'正確敘述：nefazodone是強CYP3A4抑制劑，與其底物併用可能提高藥物濃度；trazodone雖主要由CYP3A4代謝，但不是同等強度的抑制劑。', '5':'正確敘述：bupropion及其代謝物可強力抑制CYP2D6；escitalopram對該酵素抑制較弱。'}
});
Object.assign(window.DETAILED_OPTION_TRUTH,{'110-41':{A:true,B:false,C:false,D:true},'110-43':{A:true,B:true,C:false,D:false,E:true},'110-44':{A:true,B:true,C:false,D:true,E:true},'110-45':{A:false,B:false,C:false,D:true,E:true},'110-46':{A:true,B:true,C:true,D:false,E:false},'110-47':{A:false,B:true,C:true,D:true,E:true},'110-48':{A:true,B:false,C:true,D:true,E:false},'110-49':{A:true,B:false,C:true,D:false,E:true}});
delete window.DETAILED_OPTION_KEY_MISMATCH['110-44'];
Object.assign(window.DETAILED_OPTION_KEY_MISMATCH,{'110-45':'公告答案選項3納入A、D、E；但A將olanzapine列為PD精神病建議藥物，與其可能惡化運動症狀、通常避免使用的證據相矛盾。按選項內容，A、B、C均有問題，公告組合需回查原題答案。','110-47':'公告答案選項5列C、D、E而未列B；多發性梗塞造成patchy deficits是常見描述，B應為正確敘述。且題目問正確組合時，依內容應包含B、C、D、E，選項中沒有該組合，疑有答案或選項錯誤。'});
Object.assign(window.DETAILED_OPTION_NOTES,{
'110-51':{A:'正確敘述：譫妄常涉及膽鹼功能不足與多巴胺相對過度等神經傳導物質失衡；這是簡化模型，不代表所有個案都有同一種可測量缺乏。',B:'錯誤敘述：經典譫妄假說是乙醯膽鹼活性不足，而不是過多；抗膽鹼藥造成的膽鹼阻斷可誘發或加重譫妄。',C:'正確敘述：感染或組織損傷引起的發炎介質（如IL-1、IL-6、TNF-α）可能影響血腦障壁、神經傳導及腦網絡，促成急性認知改變。',D:'正確敘述：壓力反應可活化下視丘—腦下垂體—腎上腺軸，造成皮質醇調節異常；急性病、手術與睡眠剝奪可使脆弱老人更易譫妄。',E:'正確敘述：高皮質醇狀態可能影響海馬與認知網絡，與譫妄易感／持續有關；它是可能機轉之一，不是每例譫妄的必要病因。'},
'110-52':{A:'正確敘述（限研究關聯）：部分雙極疾患登錄研究發現接受鋰鹽者後續失智風險較低；治療選擇、疾病嚴重度與健康照護差異可能造成混雜，不能單憑觀察研究證明鋰鹽預防失智。',B:'錯誤敘述：登錄研究中使用鋰鹽與AD診斷的關聯不能推論鋰鹽造成AD；必須考量適應症、劑量、治療年限及反向因果等因素。',C:'錯誤敘述：低濃度環境鋰研究常探討自殺率或情緒疾患較低，而不是較高；生態相關也不能用來推論個人治療效果。',D:'正確敘述：鋰鹽可能抑制GSK-3並影響tau磷酸化、細胞存活及BDNF等神經可塑性路徑，提供神經保護假說；臨床預防效益仍未定論。'},
'110-53':{'1':'正確敘述（依該報告整理）：TBI與後續失智風險的關係可能涉及tau蛋白過度磷酸化；風險常在傷後一段時間升高並隨反覆頭傷增加，但六個月高峰是研究估計，不是所有患者固定時間軸。','2':'正確敘述（依2020 Lancet Commission引用的隊列結果）：每週高酒精攝取（>21單位）與長期戒酒者相對於中等攝取組均曾觀察到約17%較高失智風險；可能受既往疾病及戒酒原因混雜，不能直接推定因果。','3':'錯誤敘述：晚年聽力損失與失智風險升高相關（報告估計OR約1.3），但助聽器是否能直接預防失智／保護認知的因果證據尚未確立；將觀察性關聯寫成已證實保護效果過強。','4':'正確敘述：空氣污染可能透過血管與心肺疾病、氧化壓力、神經發炎及Aβ相關路徑影響腦部；各機制仍在研究，不能視為已完全證實的單一路徑。','5':'正確敘述：身體活動有助健康，WHO指南認為對一般認知正常者的認知保護效果小；MCI研究中的訊號較常見於有氧運動，但效果不等於已確立能阻止失智。'},
'110-54':{A:'正確敘述：CGA整合醫療、心理、功能、社會與環境面向，並以維持功能與制定個別照護計畫為核心。',B:'錯誤敘述：起身行走測試的常見異常切點約12秒（視版本與族群可不同），不是30秒；30秒可能代表明顯行動困難，不能作為正常界線。',C:'正確敘述：周全評估會檢視多重用藥、視聽力、步態平衡、跌倒、失禁及營養，因這些常見問題彼此交互影響且可介入。',D:'正確敘述：功能與照護可行性也取決於社會支持、經濟資源、居家安全及醫療可近性，不能只記錄ADL。',E:'正確敘述：CGA及後續整合照護可改善照護協調與功能結果，部分研究顯示降低失能或機構安置風險；效益取決於團隊能否執行建議。'},
'110-55':{A:'正確敘述：畫鐘測驗需要視空間建構、視覺搜尋與執行規劃，可發現PD認知障礙早期的視空間／執行問題；也會受教育、視力及手部動作影響。',B:'正確敘述：Benton視覺保留測驗評估視覺知覺及視覺記憶，能檢出視空間／視覺記憶缺損；它不是純視空間建構測驗，但仍是相關評估工具。',C:'正確敘述：WAIS-IV表現分測驗中的積木設計、矩陣推理等可評估視空間建構與非語文推理。',D:'錯誤敘述：倒背數字主要評估工作記憶／注意與心智操作，不直接測量視空間能力。',E:'正確敘述：Rey–Osterrieth複雜圖形臨摹可評估視空間建構、組織策略及視覺動作整合，延遲回憶另可測視覺記憶。'},
'110-56':{A:'正確敘述：快速動眼期睡眠行為障礙（RBD）是DLB核心臨床特徵之一，常早於認知症狀多年，反映α-synuclein腦幹病理。',B:'錯誤敘述：嚴重抗精神病藥敏感是DLB的支持性臨床特徵，不屬於第四版共識列出的四項核心特徵；臨床仍須避免或極審慎使用多巴胺阻斷藥。',C:'正確敘述：認知波動（注意力與清醒度變化）是DLB核心特徵，可呈恍神、嗜睡、凝視或短暫失去反應。',D:'正確敘述：反覆、鮮明且成形的視幻覺（常見人物或動物）是DLB核心特徵。',E:'正確敘述：自發性巴金森症候群是DLB核心特徵之一，常表現動作遲緩、僵硬或步態異常。'},
'110-57':{A:'正確敘述：RBD是DLB及PD常見的前驅／伴隨症狀，反映α-synuclein相關腦幹網絡受累。',B:'正確敘述：自發性巴金森症候群是DLB與PD共同的運動特徵；需以「認知障礙相對於巴金森症的時間先後」區別DLB與PDD。',C:'正確敘述：PD與DLB均可出現認知下降；PD認知障礙可在動作症狀多年後發生，DLB則認知障礙先於或與巴金森症同時出現。',D:'正確敘述：兩者都與α-synuclein聚集及Lewy小體／Lewy神經突病理相關。',E:'錯誤敘述：DLB／PDD常見的是心臟MIBG攝取降低、心臟／縱膈比值偏低，不是偏高；攝取下降可支持交感神經去神經化。'},
'110-58':{'1':'正確敘述：傳統記憶評估常分登錄（registration）、保留（retention）及回憶（recall）三階段；現代模型也會細分編碼、儲存與提取，因此術語依教材模型而異。', '2':'錯誤敘述：時間定向測驗主要測定向感，不是純粹測記憶保留；錯誤可能來自注意力、理解、語言或記憶等因素。', '3':'正確敘述：立即重複一串數字主要測立即記憶／注意廣度；若要求倒背，則額外測工作記憶及心智操作。', '4':'錯誤敘述：腦功能異常可破壞記憶保留，但心理困擾、焦慮或憂鬱也會干擾注意與編碼，進而降低後續記憶表現。', '5':'錯誤敘述：連續減7與連續減3都可評估注意／計算，難度與區辨力不同；減3通常較容易，不能僅據此說其測量「較不精確」，需依受試者教育與目的選用。'},
'110-59':{'1':'正確敘述：中風後憂鬱遠比躁症常見；躁症是較少見的中風後情感症候群。', '2':'正確敘述：中風後躁症較常與右半球，尤其右額葉／顳葉及其連結病灶相關；病灶位置關聯並非絕對。', '3':'正確敘述（依題目引用的老年躁症研究）：老年躁症患者在鋰鹽治療的反應可優於valproate；實際選藥仍需比較腎功能、甲狀腺、認知、交互作用及耐受性。', '4':'錯誤敘述：鋰鹽可造成認知遲鈍、顫抖、步態不穩、體重增加及多尿；少尿可能代表脫水或腎毒性警訊，而非一般副作用，水腫也不是典型常見效應。', '5':'正確敘述：老年人肝臟代謝與白蛋白結合變化可能延長valproate半衰期或提高游離藥比例，需監測濃度、肝功能、血小板及鎮靜等不良反應。'},
'110-60':{A:'正確敘述：AT(N)中的A代表β-amyloid病理，T代表tau病理，N代表神經退化／神經元損傷；這是研究分類框架，不是單靠檢驗就完整診斷臨床AD。', 'B':'正確敘述：若A、T、N各以陽性／陰性二分，可組成2³=8種生物標記型態；後續框架也可能採連續量值，不能把八型視為唯一表達法。', 'C':'錯誤敘述：tau病理分布及影像判讀需看軸位／冠狀位與目標腦區，不能說因病灶主要在內側基底外側顳葉就以矢狀面最佳；tau PET亦不是以單一切面決定。', 'D':'錯誤敘述：放射追蹤劑功能被對調；[18F]flortaucipir主要用於tau PET，11C-PiB用於amyloid PET。', 'E':'正確敘述：A與T標記較具AD病理特異性；N可由多種神經退化或損傷造成，特異性較低。'}
});
Object.assign(window.DETAILED_OPTION_TRUTH,{'110-51':{A:true,B:false,C:true,D:true,E:true},'110-52':{A:true,B:false,C:false,D:true},'110-54':{A:true,B:false,C:true,D:true,E:true},'110-55':{A:true,B:true,C:true,D:false,E:true},'110-56':{A:true,B:false,C:true,D:true,E:true},'110-57':{A:true,B:true,C:true,D:true,E:false},'110-58':{'1':true,'2':false,'3':true,'4':false,'5':false},'110-60':{A:true,B:true,C:false,D:false,E:true}});
Object.assign(window.DETAILED_OPTION_KEY_MISMATCH,{'110-55':'公告答案選項3包含A、C、E，但Benton Visual Retention Test也可評估視覺知覺／視覺記憶，與早期視空間缺損評估相關；題目若將「visuospatial disturbance」限定為建構能力，應補充定義，否則B亦具合理性。','110-58':'公告答案選項3為立即重複數字；但選項1所述登錄、保留、回憶也是傳統記憶評估的三階段模型，文字本身亦可成立。若本題採該教材模型，可能有兩個正確選項，需核對原始參考資料或答案。'});
Object.assign(window.DETAILED_OPTION_NOTES,{
'111-1':{A:'錯誤敘述：懷舊治療可降低部分老年人的憂鬱症狀，但沒有穩定證據顯示它明顯優於問題解決治療；不同研究的介入形式與樣本差異很大。',B:'正確敘述（研究整體趨勢）：懷舊治療與CBT均可改善老年憂鬱，部分統合分析顯示療效接近；「相當」表示研究平均效果相近，不代表每個人療效相同。',C:'正確敘述：有研究支持懷舊治療可減輕老年憂鬱症狀，尤其結構化生命回顧可協助重建意義與整合失落；它可作治療選項，不取代重症所需的完整治療。',D:'正確敘述：團體懷舊可提供同儕回應、社會連結與被肯定感，常以增進自尊、歸屬及凝聚感為目標。',E:'正確敘述：介入核心是回想並整理個人記憶與重要生命事件；治療者協助把片段經驗連成生命敘事，而非單純聊天。'},
'111-2':{A:'正確敘述：常見老人受虐分類包括身體、心理／情緒、性、財務剝削及忽視；部分分類另納入遺棄或自我忽視，分類名稱依制度略有不同。',B:'錯誤敘述：跌倒常見髖部、腕部或頭部傷害；面部拳擊傷可造成眼眶、鼻骨或顴骨損傷，但不能由下巴／顴骨折就推定是跌倒或虐待，需看傷勢分布與病史一致性。',C:'錯誤敘述：研究中的受虐性別差異不一致，女性可能因壽命較長、失能及照護依賴而在部分樣本較多，但不能把「女性更可能受虐」及「年紀越高所有類別風險都升高」概括成一致結論。',D:'正確敘述：直接責備或面質疑似加害者可能使受害者遭報復或被隔離；醫師應先確保安全、私下詢問、記錄客觀發現並依規定通報。',E:'錯誤敘述：認知障礙會使老人較難求助或敘述，但USPSTF對無症狀成人的普遍虐待篩檢證據不足，並未建議全面篩檢；臨床仍須對可疑個案作安全評估與依法處置。'},
'111-3':{'1':'正確敘述：donepezil核准用於輕、中及重度AD；此適應症不代表藥物能治癒或阻止神經退化。','2':'正確敘述：成人常用5 mg每日起始，耐受後可調至10 mg每日；是否加量要依療效、副作用與心率／體重狀況個別決定。','3':'正確敘述：噁心、嘔吐等膽鹼性腸胃副作用常見；失眠也可能發生，夜間服用若影響睡眠可由醫師調整給藥時間。','4':'錯誤敘述：donepezil提高膽鹼作用，需特別注意心搏過慢、傳導阻滯或暈厥；心搏過速不是其典型常見副作用。','5':'正確敘述（需謹慎解讀）：donepezil經肝臟代謝，肝功能受損可能改變暴露量，需監測耐受性並考慮較慢滴定或較低劑量；輕中度肝病不一定需要固定減量。'},
'111-5':{A:'錯誤敘述：強迫症在老年族群的盛行率通常不高於成年族群；老年新發強迫症較少見，需排除神經疾病、藥物及認知障礙。',B:'正確敘述：基底核—額葉迴路參與強迫症病理；基底核病變或神經退化可與晚發強迫症樣症狀相關，但並非所有病例都有可見病灶。',C:'正確敘述：儲物症常在早年開始並持續，老年人累積物品及安全風險後較容易被辨識；若比較「現患」盛行率，老年樣本可高於一般成年人。',D:'正確敘述：儲物症患者常有丟棄困難、強烈保存需求或對囤積影響缺乏病識感；不一定會承認自己有清楚的收藏衝動。',E:'正確敘述：DSM-5將儲物症列在強迫症及相關障礙類群，但它是獨立診斷，並非強迫症的一種亞型。'},
'111-6':{A:'錯誤敘述：老年自殺死亡以男性較多，特別是高齡男性；女性自殺企圖較多的族群模式不能直接套用到自殺死亡。',B:'正確敘述：童年或生命早期身體／性虐待可造成長期創傷、精神疾患與自殺風險，晚年仍可能影響脆弱性。',C:'正確敘述：腦血管疾病及相關失能、疼痛與認知變化可增加晚年憂鬱及自殺風險；屬多因素風險而非單一因果。',D:'正確敘述：急性壓力事件可能觸發絕望、失落或危機，需評估時間關聯、支持資源及自殺計畫。',E:'正確敘述：獨居可能代表社會孤立與較少日常監測；是否為風險須連同支持網絡、健康與近期變故評估。'},
'111-7':{A:'正確敘述：失智症合併妄想／幻覺常與更快的功能惡化、照護困難及較高死亡風險相關；這是群體預後關聯，不能預測每位患者。',B:'錯誤敘述：精神病性憂鬱通常病情較重、治療較困難且自殺風險不會較低；不能說雖然復發較多卻較少自殺而當成一般特徵。',C:'正確敘述：老年躁症若伴精神病症狀，通常反映較嚴重發作、較高功能受損或需較高強度治療。',D:'錯誤敘述：老年思覺失調症的負性症狀（如淡漠、退縮、動機低落）常對社會與日常功能造成長期重大影響；正性症狀也有風險，但不能說其功能影響更大。',E:'正確敘述：PD精神病與較高疾病負擔、住院、失智風險及病程複雜度相關；需檢視藥物、認知及視覺障礙等因素。'},
'111-8':{A:'錯誤敘述：老化使壓力感受器敏感度與反射反應降低，而非過強；姿勢改變時血壓調節較慢，容易姿勢性低血壓。',B:'正確敘述：虹膜擴瞳肌與自主神經反應退化、虹膜血管及結締組織變化可使瞳孔較小、暗處擴瞳較慢，影響低光視力。',C:'錯誤敘述：老年鼓膜常變厚、硬化或活動度下降，並非變薄；中耳與聽小骨僵硬也會影響傳音。',D:'正確敘述：老年交感神經張力及循環中去甲腎上腺素濃度可升高，但受體反應與反射調節變差；濃度高不代表功能反應更有效。',E:'正確敘述：唾液流量可能隨年齡、腺體疾病與藥物影響而下降，口乾常與抗膽鹼藥、多重用藥及脫水相關；健康老化本身的效應研究不完全一致。'},
'111-9':{A:'正確敘述：bvFTD早期常先出現社交行為、同理心、抑制或飲食習慣改變；AD早期則常以新學習與情節記憶下降突出。',B:'錯誤敘述：FTD可有情緒遲鈍或失控，但「VaD常缺乏關心與淡漠」不是能與FTD做固定二分的特徵；血管性病變亦可造成情緒不穩或憂鬱。',C:'正確敘述：FTD常在65歲前發病，但也可於高齡發病；年齡不是排除診斷的界線。',D:'正確敘述：bvFTD可能呈現衝動、過動與去抑制，像躁症；相較原發躁症較少持續情緒高昂、誇大及典型發作性病程。',E:'錯誤敘述：FTD患者可能淡漠、易怒或出現情緒症狀，但典型bvFTD不以悲傷罪惡、自殺意念為主；若明顯出現須評估共病憂鬱與安全風險。'},
'111-10':{'1':'錯誤敘述：基層醫療人員訓練有助辨識早期憂鬱、進行篩檢與轉介，較符合第二級預防（早期發現與處置），不是直接阻止疾病發生的第一級預防。','2':'正確敘述：計畫性追蹤可早期辨識症狀惡化並及時介入，依此題預防架構可列入第二級預防；若著重復發避免也可與第三級照護重疊。','3':'正確敘述：促進身體健康、運動、營養及慢性病管理可降低憂鬱風險，屬疾病發生前的第一級預防。','4':'正確敘述：已患病者重建並維持社交技能可改善功能、減少殘障與復發後果，屬第三級預防／復健。','5':'正確敘述：培養正向因應能力可支持已發病者復原及降低復發／功能損害，常歸入第三級預防；也可能在高風險族群作早期介入。'}
});
Object.assign(window.DETAILED_OPTION_TRUTH,{'111-1':{A:false,B:true,C:true,D:true,E:true},'111-2':{A:true,B:false,C:false,D:true,E:false},'111-5':{A:false,B:true,C:true,D:true,E:true},'111-6':{A:false,B:true,C:true,D:true,E:true},'111-7':{A:true,B:false,C:true,D:false,E:true},'111-8':{A:false,B:true,C:false,D:true,E:true},'111-9':{A:true,B:false,C:true,D:true,E:false}});
Object.assign(window.DETAILED_OPTION_KEY_MISMATCH,{'111-10':'公告答案選項3把「適當身體保健屬第一級預防」列為錯誤，但促進健康與降低疾病發生本來就是第一級預防。相反，基層醫療訓練較偏向早期辨識／第二級預防。依一般預防分級，題幹或公告答案可能有誤。'});
Object.assign(window.DETAILED_OPTION_NOTES,{
'111-11':{A:'正確敘述：自益信託由委託人以自己為受益人，可約定定期給付，協助預留生活費並降低失智後財務管理風險；信託條款須依能力尚完整時的意願規劃。',B:'正確敘述：不動產預告登記可保全請求權；登記名義人所為妨礙已登記請求權的處分，依法對該請求權人不生效力。預告登記不等於全面禁止所有處分。',C:'錯誤敘述：監護宣告聲請的親屬範圍是四親等內，不是六親等內；另包括本人、配偶、最近一年有同居事實的其他親屬、檢察官、主管機關、社會福利機構等法定聲請人。',D:'正確敘述：聯徵中心金融註記可供民眾表達不再申辦信用卡、貸款或擔任保證人的意願，讓金融機構受理相關申請時查核；它不是法院宣告，也不會替代財產信託。',E:'錯誤敘述：特別代理人可在法院指定範圍內代理程序，但涉及捨棄、認諾、撤回或和解等重大處分行為，須有特別授權或法院許可；不能概括說一經選任就可無限制行使。'},
'111-12':{A:'正確敘述：量表只能協助篩檢或量化症狀，不能取代完整病史、精神狀態、身體檢查及知情者資料；分數須放回臨床脈絡解讀。',B:'錯誤敘述：HAM-D並非普遍比MADRS更適合高齡者；HAM-D含較多睡眠、食慾及身體症狀項目，可能受共病干擾，工具選擇要看評估目的與受試者狀態。',C:'正確敘述：GDS刻意減少睡眠、食慾、體重等身體症狀題目，以降低老年身體疾病造成的混淆；仍需臨床確認，不能單靠量表診斷。',D:'正確敘述：認知量表會受教育、基線智力、文化、語言、視聽力與熟悉度影響；相同分數不代表不同背景者有相同認知狀態。',E:'錯誤敘述：MMSE包含時間／地點定向、登錄、注意計算、短延遲回憶、語言與視空間建構，並沒有一個獨立的長期記憶測驗。'},
'111-13':{A:'錯誤敘述：disulfiram可引起嚴重酒精反應，且高齡者常有心血管、肝臟、認知與多重用藥風險，通常不是老年酒精依賴的安全常規選擇。',B:'錯誤敘述：acamprosate獲FDA核准用於維持戒酒，但老年族群專屬療效資料有限；腎功能不全須調整，嚴重腎損害禁用，不能概括說對所有老人已證實有效。',C:'正確敘述：老年人酒精戒斷可能延長或較複雜，代謝、肝功能、共病及神經儲備差異會影響病程；須監測譫妄、癲癇及電解質。',D:'正確敘述：acamprosate可調節麩胺酸／GABA平衡，降低戒酒後神經興奮性，主要用於維持戒酒而非治療急性戒斷。',E:'正確敘述：naltrexone阻斷μ-opioid受體，可降低酒精渴求及重度飲酒／復發風險；開始前要確認無使用阿片類並評估肝臟狀況。'},
'111-14':{A:'錯誤敘述：SCEA確有12題性知識K-Scale與5題安全技巧S-Scale，但原工具是為認知障礙／智能障礙者的性同意能力與教育需求設計，並非專為失智症患者建立或驗證；不可把工具用途說得過窄。',B:'正確敘述（依該行為分類回顧）：失智者尋求親密的接吻、擁抱較常在AD被描述；明顯去抑制行為較常見於額葉／其他失智類型，但不同病型也會重疊。',C:'正確敘述（概念模型）：理解性情境涉及注意與語意知識、既往經驗、對安全做法的記憶及執行／推理能力；各記憶系統是分析能力的框架，實際同意評估不可只以單一認知測驗代替。',D:'正確敘述：功能能力訪談常聚焦理解資訊、推理選擇及自願表達選擇等能力；須針對當下具體性行為與對象評估，而非僅看診斷或總體認知分數。',E:'錯誤敘述：失智診斷不會自動代表無性同意能力；能力具情境特異性，需評估理解、風險、自由選擇及是否受脅迫，並兼顧本人性自主與他人安全。'},
'111-15':{A:'正確敘述：BPD患者衝動、自傷及高風險行為常隨年齡下降；晚年仍可能以自我忽略、不遵醫囑、物質使用或自我照顧失調呈現持續困難。',B:'正確敘述：DSM-5人格疾患診斷要求模式可追溯至成年早期；沒有腦病或物質因素時，晚年新發人格改變的病因歸屬仍有爭議，需先評估神經、藥物與情境因素。',C:'錯誤敘述：若人格病理模式首次在老年才出現，不能不加鑑別就診斷人格疾患；需確認長期跨情境模式，並排除失智、額葉病變、藥物及身體疾病。',D:'錯誤敘述：額葉／額顳葉疾病可能破壞社會規範、同理心、情緒辨識與抑制控制，反而會模仿或造成類人格改變；這些功能受損不是「尚不至於明顯」的保留領域。',E:'正確敘述：人格特質可能在中年後表面減弱，晚年遭遇失落、疾病與依賴時重新突出；需判斷是既有模式復現，還是新發神經精神變化。'},
'111-16':{A:'正確敘述：共享決策至少需要醫療專業人員與病人共同參與；病人可邀請家屬或代理人，但不能取代其本人有能力時的參與。',B:'錯誤敘述：資訊角色顛倒。醫療人員提供各方案的實證、利益與風險；病人表達價值、偏好、生活目標與可接受負擔。',C:'正確敘述：雙方討論選項並整合證據與偏好，以形成對該病人最可行、符合價值的決策，而非追求抽象唯一最佳答案。',D:'正確敘述：醫師有責任以可理解方式說明可行方案及各自的好處、傷害、不確定性與不治療選項。',E:'錯誤敘述：共享決策不是病人服從醫師主導；醫師可提供專業建議，但須保留病人參與、提問與表達選擇的空間。'},
'111-17':{A:'正確敘述（典型比較）：譫妄視幻覺常較鮮明、混亂或令人恐懼，內容會隨急性病因及清醒度波動；但是否恐怖並非診斷必要條件。',B:'正確敘述：急性譫妄常伴睡醒週期逆轉與夜間惡化，可能早期出現；AD睡眠節律改變通常隨病程逐漸發生。',C:'正確敘述：譫妄會造成注意力及思考組織急性受損，早期即可答非所問、思緒跳躍或語言不連貫。',D:'錯誤敘述：錯認可出現在AD，但通常不是早期核心表現；早期較典型是新學習與情節記憶下降，錯認多在病程進展或合併其他因素時出現。',E:'正確敘述：注意力不集中、無法維持注意及清醒度／認知波動是譫妄核心特徵，常在數小時至數日內急性發生。'},
'111-18':{A:'正確敘述：donepezil半衰期約70小時（近3日），經CYP2D6及CYP3A4代謝，部分以原型或代謝物由尿液排出；故停藥或調整後效應不會立即消失。',B:'錯誤敘述：rivastigmine口服血漿半衰期約1–2小時，通常每日兩次；貼片每日更換是因持續釋放，不代表血中半衰期12小時。',C:'正確敘述：貼片與較高劑量口服rivastigmine可有相近臨床療效，貼片峰值較平緩且腸胃道不良反應較少；仍可能皮膚刺激或食慾下降。',D:'正確敘述：galantamine不建議用於嚴重肝功能不全；肝臟代謝降低會提高暴露量，輕中度損害也須減量或延長滴定。',E:'正確敘述：藥物過敏是絕對禁忌；心搏過慢、傳導阻滯或暈厥風險是重要相對禁忌／警訊，需監測脈搏與心電圖及合併用藥。'},
'111-19':{A:'錯誤敘述：睡眠時數與死亡風險研究常呈U型，短睡與長睡都可能相關；不能概括說各大型研究中短睡比長睡更常與高死亡風險相關。',B:'正確敘述：長睡可能是衰弱、慢性病、憂鬱、活動減少或睡眠品質差的表徵，不一定是睡得久直接造成體能退化。',C:'錯誤敘述：主觀睡眠時間增加不代表身心健康更好；過長睡眠可能與疾病、白天嗜睡、功能下降及死亡風險相關。',D:'正確敘述（依題目引用的本土研究）：自述睡眠達8小時以上曾與肌少症、肌力較差等亞臨床指標相關；屬觀察性關聯，可能反映既有健康狀況或活動量，不證明睡眠長直接致病。'},
'111-20':{A:'正確敘述（群體趨勢）：男性妄想症患者平均發病年齡可能較女性早；性別差異在不同研究與樣本中不一致，不能用於個人診斷。',B:'正確敘述：妄想症患者通常比思覺失調症患者保留較多認知與社會功能；有小型研究發現神經心理缺損差異不顯著，但樣本量有限，並非認知完全正常。',C:'錯誤敘述：妄想症沒有一致、特異的MRI診斷型態；老年人常見的腦萎縮或白質高訊號可能是共病、血管負荷或年齡相關的非特異發現，不能概括為妄想症患者的典型影像。',D:'正確敘述：聽力下降與晚年妄想／精神病的關聯仍受研究方法與樣本影響，尚不能確認為單一直接因果；臨床仍應檢查感官障礙，因其會加劇誤解與被害解讀。',E:'正確敘述：若妄想只在明確情緒發作期間出現，應考慮情感疾患伴精神病特徵；妄想症可合併短暫情緒症狀，但妄想須在情緒發作之外存在，且情緒發作不占病程主要部分。'}
});
Object.assign(window.DETAILED_OPTION_TRUTH,{'111-11':{A:true,B:true,C:false,D:true,E:false},'111-12':{A:true,B:false,C:true,D:true,E:false},'111-13':{A:false,B:false,C:true,D:true,E:true},'111-14':{A:false,B:true,C:true,D:true,E:false},'111-15':{A:true,B:true,C:false,D:false,E:true},'111-16':{A:true,B:false,C:true,D:true,E:false},'111-17':{A:true,B:true,C:true,D:false,E:true},'111-18':{A:true,B:false,C:true,D:true,E:true},'111-19':{A:false,B:true,C:false,D:true},'111-20':{A:true,B:true,C:false,D:true,E:true}});
const q11121=window.EXAM_QUESTIONS.find(q=>q.year===111&&q.number===21);
if(q11121){q11121.text='21. 關於老年憂鬱症描述，何者錯誤？\n1. 血管性憂鬱症以冷漠表情及缺乏動機為主要症狀。\n2. 腦衍生神經營養因子(brain derived neurotrophic factor)活性下降為可能之致病原因。\n3. 血管性憂鬱症的核磁共振影像中，常出現白質影像增強(white matter hyperintensities)。\n4. 腦中風後憂鬱症(post-stroke depression)在腦中風後6個月內的流行率達到最高。\n5. 老年自殺在神經生物上的研究，顯示和血清素(serotonin)活性上升有關。';q11121.options=[1,2,3,4,5].map(n=>({n,text:['血管性憂鬱症以冷漠表情及缺乏動機為主要症狀。','腦衍生神經營養因子(BDNF)活性下降為可能之致病原因。','血管性憂鬱症的MRI常出現白質高訊號(white matter hyperintensities)。','腦中風後憂鬱症在腦中風後6個月內的流行率達到最高。','老年自殺在神經生物學研究中，顯示和血清素活性上升有關。'][n-1]}));q11121.statements=q11121.options.map(o=>({letter:String(o.n),text:o.text}));}
const q11126=window.EXAM_QUESTIONS.find(q=>q.year===111&&q.number===26);
if(q11126){q11126.text='26. 下列關於巴金森氏症(Parkinson’s disease)與睡眠障礙之描述，何者錯誤？\n1. 巴金森氏症病人大約60%-90%有睡眠困擾。\n2. 病人出現原因不明(idiopathic)的RBD會增加未來罹患巴金森氏症與失智症風險。\n3. 上述風險與α-synuclein pathology有關，平均追蹤5年後有20%-40%風險。\n4. 有研究顯示低劑量zolpidem可幫助減少巴金森氏症病人的dyskinesia症狀。\n5. 治療巴金森氏症的dopaminergic藥物會造成病人後半段睡眠無法維持及早醒問題。';q11126.options=[1,2,3,4,5].map(n=>({n,text:['巴金森氏症病人大約60%-90%有睡眠困擾。','原因不明的RBD會增加未來罹患巴金森氏症與失智症的風險。','RBD轉化風險與α-synuclein病理有關，平均追蹤5年後約20%-40%。','低劑量zolpidem曾被研究用於減少巴金森氏症患者dyskinesia。','治療巴金森氏症的dopaminergic藥物會造成後半夜睡眠維持困難及早醒。'][n-1]}));q11126.statements=q11126.options.map(o=>({letter:String(o.n),text:o.text}));}
Object.assign(window.DETAILED_OPTION_NOTES,{
'111-21':{'1':'正確敘述：血管性憂鬱常以淡漠、動機不足、精神動作遲滯與執行功能缺損突出；情緒性悲傷或罪惡感有時不明顯。','2':'正確敘述：BDNF支持神經元存活與突觸可塑性，活性下降是晚年憂鬱可能涉及的神經生物機轉之一；目前不是單一確定病因或臨床診斷檢驗。','3':'正確敘述：血管性憂鬱常見腦白質高訊號及小血管病變，可能破壞額葉—皮質下情緒與執行迴路；影像需與年齡及血管風險一併解讀。','4':'正確敘述（依題目所引研究）：中風後憂鬱在中風後數月內盛行率常較高，約六個月內可達高峰；各研究高峰時間依評估方式及樣本而異。','5':'錯誤敘述：老年自殺與血清素功能降低／調節異常的研究較多，並非單純活性上升；神經生物學關聯不能直接當作個人自殺風險檢測。'},
'111-22':{A:'正確敘述：退縮與依賴特質可能增加人際孤立、低自我效能及憂鬱脆弱性；關聯不代表人格診斷是憂鬱的必要條件。',B:'錯誤敘述：人格問題常見於早發、慢性或反覆憂鬱；晚發憂鬱相較早發未必有更多人格病理，且晚年新發人格改變應排除腦病。',C:'正確敘述（依研究趨勢）：慢性輕鬱／持續性憂鬱症較常與長期人格問題共存；重鬱症患者的人格共病比例不必然更高。',D:'正確敘述：神經質、焦慮與強迫特質會增加對失落與壓力的敏感、反覆擔憂及僵化因應，可能提高老年憂鬱風險。',E:'正確敘述：一生缺乏親密連結會減少社會支持與壓力緩衝，屬憂鬱風險因子之一。'},
'111-23':{A:'正確敘述：中年期高血壓是可修正的失智風險因子；控制血壓可降低血管傷害，特定SBP目標需依共病、衰弱與耐受性個別決定。',B:'正確敘述：每週飲酒超過21單位屬高量飲酒，與認知及失智風險相關；減量可降低酒精與血管傷害。',C:'正確敘述：戒菸無論年齡都可改善心肺與血管健康並減少持續暴露；認知效益可能受既往累積暴露影響，但仍值得鼓勵。',D:'錯誤敘述（依本題個人層級分類）：減少職業／交通中的嚴重腦傷主要仰賴環境安全規範、職場及交通政策，屬人口或政策層級策略；個人安全措施仍有益，但不屬本題指定的個人臨床策略組。',E:'錯誤敘述：降低空氣污染暴露的國家／國際政策屬人口政策層級，不是個人患者層次的直接風險管理措施。'},
'111-24':{A:'錯誤敘述：老年憂鬱中的人格問題並非「輕型憂鬱一定比重鬱更多」；人格共病會隨慢性度、病程、樣本及診斷方式變化。',B:'正確敘述：退縮、依賴人格特質與老年憂鬱及其持續性有關，可能削弱主動因應並增加社會孤立。',C:'正確敘述（需避免絕對解讀）：親密關係與社會支持會調節生活事件對憂鬱的影響；缺乏支持時負向事件的關聯較強，但不是只有缺乏親密關係者才會受生活事件影響。',D:'正確敘述：葉酸與維生素B群不足可影響單胺合成、同半胱胺酸代謝與認知，低濃度與憂鬱合併認知缺損相關；應檢查並處理可逆缺乏。',E:'正確敘述：單胺假說無法完整解釋憂鬱病理及抗憂鬱劑延遲起效；神經可塑性、壓力軸、血管、發炎及心理社會因素亦參與。'},
'111-25':{A:'正確敘述：統合分析發現譫妄與長期認知下降相關；即使原本認知已有缺損，譫妄後仍可能出現額外下降。',B:'錯誤敘述：基線認知正常者譫妄後仍可能有顯著長期認知下降；沒有顯著結果可能受研究數量、追蹤及統計力影響，不能視為無風險。',C:'正確敘述（依統合分析敏感度分析）：控制基線認知後，譫妄與後續下降的關聯仍存在，部分分析中效應反而更清楚；基線校正可降低既有認知差異的混淆。',D:'正確敘述（因果需保留）：譫妄可能造成神經發炎、網絡損傷或揭露腦儲備不足，具生物合理性；目前觀察性研究尚不能證明譫妄是唯一直接原因。',E:'正確敘述：該統合分析指出譫妄與長期認知下降的關聯在手術與非手術樣本沒有顯著差別；研究異質性仍需考量。'},
'111-26':{'1':'正確敘述：PD患者睡眠問題十分常見，研究估計約60–90%，包括失眠、日間嗜睡、RBD、睡眠呼吸障礙及夜間運動症狀。','2':'正確敘述：孤立性RBD是α-synuclein疾病重要前驅症狀，可轉化為PD、DLB或多系統萎縮；風險隨追蹤時間上升。','3':'正確敘述（群體估計）：部分隊列追蹤五年後轉化風險約20–40%，但轉化率受年齡、轉診樣本及追蹤期影響，不是固定個人預測。','4':'正確敘述（有限證據）：低劑量zolpidem曾在小型研究中用於改善PD患者dyskinesia；屬非標準／有限研究用途，須注意跌倒、譫妄與鎮靜風險。','5':'錯誤敘述：多巴胺能藥物對睡眠的影響因藥物與劑量而異；有些會造成嗜睡或睡眠發作，也可能改善夜間動作症狀，不能概括說都造成後半夜失眠與早醒。'},
'111-27':{'1':'錯誤敘述：失智症診斷要求認知下降已干擾獨立日常或社會／職業功能；若仍維持獨立，可能較符合輕度認知障礙。','2':'正確敘述：DLB核心特徵之一是認知波動，表現為注意、清醒程度與認知效能在一天或不同日間明顯變化。','3':'錯誤敘述：DLB核心幻覺是反覆、鮮明的視幻覺；聽幻覺可出現但不是核心特徵，也不是高達80%的核心診斷指標。','4':'錯誤敘述：自發性巴金森症候群是核心特徵且在DLB相當常見；估計約50%低估多數臨床隊列，常隨病程出現，不能用此比例否定其重要性。','5':'錯誤敘述：RBD確是DLB核心特徵，但死後病理比較中DLB與非DLB的RBD比例差異通常遠大於70%對40%；共識報告約76%對4%，題目數值不符且會高估非DLB組。'},
'111-28':{'1':'錯誤敘述：晚發型思覺失調症通常定義為40歲或45歲後發病；65歲後才發病是VLOSLP的界線，不是LOS定義。','2':'錯誤敘述：晚發型患者常見被害妄想，並非較少；被偷妄想可出現但不是相較早發型的特定主型。','3':'錯誤敘述：LOS患者病前社會功能通常較早發型保留，日常功能不必然較差；功能結果仍受認知、症狀與共病影響。','4':'錯誤敘述：晚發型思覺失調症通常較少正式思考障礙，妄想較系統化；不能說思考障礙較多。','5':'正確敘述：相較早發型，晚發型患者平均負性症狀較少，病前功能較佳；高齡女性與感官障礙等因素仍須鑑別。'},
'111-29':{A:'錯誤敘述：常染色體顯性遺傳是家族型早發AD的典型遺傳方式，不是隱性遺傳。',B:'正確敘述：APP、PSEN1、PSEN2的致病變異可造成常染色體顯性家族型早發AD。',C:'正確敘述：PSEN1位於第14號染色體（14q24.2），致病變異是家族型早發AD的重要原因。',D:'正確敘述：PSEN2位於第1號染色體（1q42.13）。',E:'正確敘述（依題目引用估計）：PSEN1變異占早發家族型AD相當比例，報告範圍約18–55%，因家族選樣與族群而異；此不是所有早發AD患者的比例。'},
'111-30':{A:'正確敘述：CGA整合醫療、心理、功能、社會與環境資料，並追蹤功能變化以訂出個別照護計畫。',B:'錯誤敘述：TUG走10英尺35秒不可能視為正常；較長完成時間提示行動／平衡障礙與跌倒風險，常用異常界值約12秒上下，依族群而異。',C:'正確敘述：多重用藥、視聽力、步態平衡、跌倒、失禁及營養都是CGA常規評估項目，可發現多因性可介入問題。',D:'正確敘述：ADL之外還要評估社會支持、經濟來源、居家安全與醫療可近性，因這些決定照護計畫能否落實。',E:'正確敘述：居家或社區CGA若配合後續服務，可改善功能、照護協調並降低失能與機構安置風險；效益取決於介入是否實際完成。'}
});
Object.assign(window.DETAILED_OPTION_TRUTH,{'111-21':{'1':true,'2':true,'3':true,'4':true,'5':false},'111-22':{A:true,B:false,C:true,D:true,E:true},'111-23':{A:true,B:true,C:true,D:false,E:false},'111-24':{A:false,B:true,C:true,D:true,E:true},'111-25':{A:true,B:false,C:true,D:true,E:true},'111-26':{'1':true,'2':true,'3':true,'4':true,'5':false},'111-27':{'1':false,'2':true,'3':false,'4':false,'5':false},'111-29':{A:false,B:true,C:true,D:true,E:true},'111-30':{A:true,B:false,C:true,D:true,E:true}});
Object.assign(window.DETAILED_OPTION_KEY_MISMATCH,{'111-27':'公告答案選項2標示認知波動為正確；但選項5也正確指出RBD是DLB核心特徵，僅其「70%對40%」數值不符共識報告所列病理確認樣本（約76%對4%）。此為複合敘述，需區分核心特徵本身與比例錯誤。'});
const q11132=window.EXAM_QUESTIONS.find(q=>q.year===111&&q.number===32);
if(q11132){q11132.text='32. 關於老年躁症的治療，下列何者正確？\n1. Lithium及非典型抗精神病藥物為治療老年躁症的第一線用藥。\n2. Valproate及Lithium對老年躁症的耐藥性及安全性比Lamotrigine高。\n3. 老年病人需要從低劑量慢慢增加劑量，腦部疾病者可以用較高劑量。\n4. 開始治療急性躁症後，應至少持續3-4週。\n5. 年輕就開始使用Lithium的躁症病患不用注意中毒風險。';q11132.options=[1,2,3,4,5].map(n=>({n,text:['Lithium及非典型抗精神病藥物為治療老年躁症的第一線用藥。','Valproate及Lithium對老年躁症的耐受性及安全性比Lamotrigine高。','老年病人需要低劑量慢慢增加劑量，腦部疾病者可以用較高劑量。','開始治療急性躁症後，應至少持續3-4週。','年輕就開始使用Lithium的躁症患者不用注意中毒風險。'][n-1]}));q11132.statements=q11132.options.map(o=>({letter:String(o.n),text:o.text}));}
Object.assign(window.DETAILED_OPTION_NOTES,{
'111-31':{A:'正確敘述：全球失智盛行率估計約5–7%，隨年齡大幅上升；國家、年齡結構及診斷方式會使估計值變動。',B:'錯誤敘述：失智盛行率會隨年齡增加，但不是每增加5歲就必然倍增，也沒有可信的一般族群估計說95歲以上80%均罹病；極高齡研究的樣本與存活偏差很大。',C:'正確敘述（作為群體估計）：女性AD患者數可約為男性兩倍，部分與女性較長壽及年齡結構有關；年齡標準化後差異較小，並非女性個人風險固定兩倍。',D:'正確敘述：Alzheimer於1906年描述病例；APOE位於19號染色體，ε4是最早確立的常見晚發AD風險等位基因之一，但不是造成家族型AD的致病突變。',E:'錯誤敘述：BPSD可隨病程增加，但常波動、受環境與生理誘因影響，也可能某些症狀緩解；不能說所有患者症狀必然越來越頻繁且持續加劇。'},
'111-32':{'1':'正確敘述的可能性有限：鋰鹽是老年躁症重要一線選項；但把非典型抗精神病藥一概列為老年躁症第一線過於概括，需依失智、心血管、跌倒及代謝風險選擇。', '2':'錯誤敘述：鋰鹽與valproate是急性躁症主要治療，但「耐受性及安全性比lamotrigine高」不是可概括結論；lamotrigine並非急性躁症治療藥，且高齡者的安全性須個別比較。', '3':'錯誤敘述：高齡患者應低劑量起始、慢慢調整；腦部疾病、腎功能不全或神經脆弱反而需更審慎，不能因腦病而提高劑量。', '4':'正確敘述（依題目教材的急性期觀察）：躁症治療需給足治療時間並監測反應，數週內評估改善；3–4週不是所有患者一律固定的最低療程，若惡化、無效或不耐受須及早調整。', '5':'錯誤敘述：長期鋰鹽患者仍會因老化、脫水、腎功能下降、感染或交互作用而發生中毒；應持續監測血中濃度、腎、甲狀腺與電解質。'},
'111-33':{A:'錯誤敘述：多數受虐研究顯示女性受害者較多，部分可能與女性壽命較長及失能／照護依賴有關；性別比例會依虐待類型和樣本改變。',B:'正確敘述：失智會增加依賴、溝通困難及對照護者的依賴，降低求助能力，因而提高受虐或忽視風險。',C:'正確敘述：與配偶以外多名家庭成員同住可能增加家庭衝突、照顧壓力及財務接觸，與受虐風險上升相關；同住本身並非因果證明。',D:'正確敘述：低收入與情緒／身體虐待風險相關，可能透過資源匱乏、照護壓力及權力不平衡作用。',E:'錯誤敘述：低收入不會保護老人免於財務剝削；經濟依賴、財產管理困難及社會弱勢也可能增加被剝削風險。'},
'111-34':{A:'錯誤敘述：人格病理整體可使憂鬱治療較複雜，但現有資料不足以把「畏避型人格」單獨說成老年MDD較差預後的確立指標；不能把一般人格共病結果外推到特定亞型。',B:'錯誤敘述：醫療問題與社交機會減少可能讓老人看起來依賴，但需要依長期跨情境人格模式診斷；題目將社會限制直接說成容易被過度診斷，並非穩定的流行病學結論。',C:'正確敘述（依題目引用的老年人格教材）：強迫型人格的一些僵化、完美主義表現可能隨晚年角色與生活要求改變而減輕；變化不等於每人都緩解。',D:'錯誤敘述：類分裂型特質可能持續，但不能概括說症狀在晚年「通常持續」；孤獨、社交網絡縮小與退休也會改變表面行為，診斷需有長期病史。',E:'正確敘述（限老年受刑人樣本）：反社會人格特徵在部分老年監獄族群仍可觀察到，盛行率未必隨年齡下降；一般社區與監獄樣本不可互相外推。'},
'111-35':{A:'錯誤敘述：血管病變可增加晚年憂鬱風險，但不能說單一血管病因就足以造成憂鬱發作；需看病灶位置、既有脆弱性與心理社會因素。',B:'錯誤敘述：失志（demoralization）可伴無助、失敗感與缺乏意義，但不等同重鬱；神經植物症狀並非其必然特徵，症狀改善通常也應重新評估希望感，題述概括不成立。',C:'錯誤敘述：老年雙相患者即使情緒平穩仍可能有認知缺損，研究估計因測驗、疾病發病年齡及共病差異很大；不能以「約四分之一」作普遍固定比例。',D:'正確敘述（依全球比較估計）：在許多高齡國家，65歲以上人口占比約一成以上，但自殺死亡中高齡者的占比可約為其人口比例兩倍；國家與性別差異很大。',E:'正確敘述：老年雙相疾患常合併多種身體共病，研究平均可有約3–4項；共病增加藥物交互作用及功能負擔。'},
'111-36':{A:'錯誤敘述：CES-D原版是20題、四點頻率作答的自填量表，不是30題二分作答；另有短版等不同版本。',B:'錯誤敘述：常用GDS長版30題、短版15題；題目所稱20題並非最常用標準版本，需標明具體修訂版。',C:'正確敘述：GDS題目涵蓋認知／自我評價、情緒、自我形象與失落等主觀憂鬱內容，並刻意減少身體症狀題目以降低老年共病混淆。',D:'正確敘述：MADRS常用於臨床試驗與治療反應評估；社區篩檢較常使用CES-D或GDS，MADRS社區常模及應用較不標準化。',E:'正確敘述：MADRS有10項，每項0–6分，總分0–60分；分數越高代表憂鬱症狀越嚴重。'},
'111-37':{'1':'錯誤敘述：此型態A−T−(N)−代表沒有AD核心生物標記；患者仍可能有主觀記憶抱怨，但不符合該框架的AD病理定義。','2':'錯誤敘述：A−T−(N)+表示無amyloid／tau陽性但有神經退化標記，不符合已見amyloid PET陽性的個案。','3':'正確敘述：amyloid PET輕度陽性表示A+；題幹沒有tau或神經退化標記陽性證據，故為A+T−(N)−。認知未達失智不能取消生物標記分類。','4':'錯誤敘述：A+T+(N)−要求tau病理也陽性；題幹只提供amyloid PET陽性，沒有tau標記結果。','5':'錯誤敘述：A+T−(N)+需要有神經退化／神經損傷證據；單純輕度主觀記憶抱怨及amyloid PET陽性不足以判為N+。'},
'111-38':{A:'正確敘述：老年人飲酒及用藥問題常被低估、低報告，可能因羞恥、記憶困難、醫療人員未詢問或把症狀歸於老化。',B:'錯誤敘述：照顧機構盛行率並非穩定低於社區；機構住民的疾病、用藥與照護限制會影響飲酒辨識及報告，研究估計依場域而異。',C:'錯誤敘述：接受治療的老年人常有不錯的治療留存與結果，不可一概說預後比年輕人差；共病與衰弱會改變個別療程。',D:'正確敘述：老年患者在部分研究中治療完成率較高，可能因較重視健康後果、較少工作／家庭干擾及較多結構化支持。',E:'正確敘述：年齡更高的老人酒精使用障礙盛行率通常下降，可能與飲酒量減少、存活偏差及世代差異相關。'},
'111-39':{A:'錯誤敘述：部分研究發現老年患者治療留存或完成率不低於年輕者，並非一致較低；不能把較多共病直接推成較差完成率。',B:'正確敘述：年長者可能有較高團體治療出席率，治療結構與同儕支持有助維持參與；研究結果仍受方案與樣本影響。',C:'錯誤敘述：年齡相近的治療團體可能提高認同與參與，不是降低戒酒成功率的確定因素；結果需看對照方式及介入內容。',D:'正確敘述：老年女性接受酒精治療後在部分研究中戒酒率較男性高；但樣本、病程及家庭支持可影響性別差異。',E:'正確敘述：在未完全戒酒的患者中，男性平均大量飲酒日數可能較女性多；這是群體平均，臨床仍要個別詢問飲酒量。'},
'111-40':{A:'正確敘述：Trail Making、Stroop及Wisconsin Card Sorting均涉及抑制、轉換、規劃或概念形成，常用於執行功能評估；也會受視力、動作速度及教育影響。',B:'錯誤敘述：RAVLT及HVLT-R主要測語文學習、延遲回憶與再認記憶，不是一般語言能力測驗。',C:'錯誤敘述：Judgment of Line Orientation及constructional praxis主要測視空間判斷與視覺建構，並非sensorimotor能力的代表工具。',D:'正確敘述：MMSE與ADAS-Cog均含時間／地點定向或相關定向題，可評估部分定向能力；兩者測試範圍與分數不能互換。',E:'錯誤敘述：MMPI-2可用於老年人，但要考量教育、視聽力、疲勞、認知障礙及常模適切性；不能說完全不適合。'}
});
