const q10729=window.EXAM_QUESTIONS.find(q=>q.year===107&&q.number===29);
if(q10729){
q10729.text='29. 有關老年族群的憂鬱，以下何者有誤？\n選項：\n1. DSM診斷系統顯示因為憂鬱症狀在不同年紀可能有不同臨床表現，所以DSM-5針對老年憂鬱訂有特別診斷準則。\n2. 文獻回顧發現，和年輕及中年族群相比，老年族群重度憂鬱發生率較低；進一步分析發現持續性憂鬱症（Dysthymia）和輕度憂鬱症（Minor Depression）在老年族群發生率較高。\n3. 文獻回顧和追蹤研究顯示，老年族群憂鬱常有預後較差的趨勢。\n4. 證據顯示老年族群憂鬱發作的急性期治療並沒有比成年族群困難。\n5. 相對於成年族群，老年族群有更多心理和社會保護因子可協助對抗憂鬱，但若干生物因子也會明顯影響憂鬱風險。';
q10729.options=[{n:1,text:'DSM診斷系統顯示因為憂鬱症狀在不同年紀可能有不同臨床表現，所以DSM-5針對老年憂鬱訂有特別診斷準則。'},{n:2,text:'文獻回顧發現，和年輕及中年族群相比，老年族群重度憂鬱發生率較低；進一步分析發現持續性憂鬱症（Dysthymia）和輕度憂鬱症（Minor Depression）在老年族群發生率較高。'},{n:3,text:'文獻回顧和追蹤研究顯示，老年族群憂鬱常有預後較差的趨勢。'},{n:4,text:'證據顯示老年族群憂鬱發作的急性期治療並沒有比成年族群困難。'},{n:5,text:'相對於成年族群，老年族群有更多心理和社會保護因子可協助對抗憂鬱，但若干生物因子也會明顯影響憂鬱風險。'}];
q10729.statements=q10729.options.map(o=>({letter:String(o.n),text:o.text}));
}
